49	/**
50	 * Builds router location parts after mutating search params while preserving the current hash.
51	 *
52	 * If `source.hash` is omitted, reads the live `window.location.hash`. The dialog deep-link
53	 * code mutates the hash via `history.replaceState`, which doesn't update React Router's
54	 * `useLocation()`, so callers that read `location` from React Router must pass the hash
55	 * explicitly or omit it (in which case we read live).
56	 */
57	export function buildEvalUrlWithSearchParams(
58	  source: { pathname: string; search: string; hash?: string },
59	  mutateSearchParams: (params: URLSearchParams) => void,
60	): EvalUrlParts {
61	  const nextSearchParams = new URLSearchParams(source.search);
62	  mutateSearchParams(nextSearchParams);
63	  const nextSearch = nextSearchParams.toString();
64	
65	  let hash: string;
66	  if (source.hash !== undefined) {
67	    hash = source.hash;
68	  } else if (typeof window === 'undefined') {
69	    hash = '';
70	  } else {
71	    hash = window.location.hash;
72	  }
73	
74	  return {
75	    pathname: source.pathname,
76	    search: nextSearch ? `?${nextSearch}` : '',
77	    hash,
78	  };
79	}
