148	export function hashVarSchema(varNames: string[]): string {
149	  // Sort to ensure consistent hash regardless of original order
150	  const sorted = [...varNames].sort();
151	  // Use JSON.stringify for robust serialization that handles any characters
152	  return JSON.stringify(sorted);
153	}
