157	 * @param output - The evaluation output to check
158	 * @returns true if the output has a human rating in componentResults
159	 */
160	export function hasHumanRating(output: EvaluateTableOutput | null | undefined): boolean {
161	  if (!output?.gradingResult?.componentResults) {
162	    return false;
163	  }
164	  return output.gradingResult.componentResults.some(
165	    (result) => result?.assertion?.type === HUMAN_ASSERTION_TYPE,
166	  );
167	}
