171	 * @param output - The evaluation output to search
172	 * @returns The human rating componentResult or undefined if none exists
173	 */
174	export function getHumanRating(output: EvaluateTableOutput | null | undefined) {
175	  if (!output?.gradingResult?.componentResults) {
176	    return undefined;
177	  }
178	  return output.gradingResult.componentResults.find(
179	    (result) => result?.assertion?.type === HUMAN_ASSERTION_TYPE,
180	  );
