185	export function getNamedMetricTotal(
186	  metrics: NamedMetricTotalsSource | null | undefined,
187	  metric: string,
188	): number {
189	  return metrics?.namedScoreWeights?.[metric] ?? metrics?.namedScoresCount?.[metric] ?? 0;
