191	
192	export function getNamedMetricTotals(
193	  metrics: NamedMetricTotalsSource | null | undefined,
194	): Record<string, number> | undefined {
195	  if (!metrics?.namedScoresCount && !metrics?.namedScoreWeights) {
196	    return undefined;
197	  }
198	
199	  return {
200	    ...(metrics.namedScoresCount ?? {}),
201	    ...(metrics.namedScoreWeights ?? {}),
202	  };
